import{_ as s,a0 as i,w as l,s as u,ao as a,I as p,x as t,a1 as n,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"微软加入开放 3D 基金会，参与开源 3D 开发 | LCTT x X-CMD","titleTemplate":false,"description":"微软加入开放 3D 基金会，参与开源 3D 开发 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"微软加入开放 3D 基金会，参与开源 3D 开发 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"微软加入开放 3D 基金会，参与开源 3D 开发 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220502 Microsoft Joins The Open 3D Foundation For Open Source 3D Development","title":"微软加入开放 3D 基金会，参与开源 3D 开发","tag":"202205","desc":""},"relativePath":"202205/20220502 Microsoft Joins The Open 3D Foundation For Open Source 3D Development.md","filePath":"[post].md"}'),d={name:"202205/20220502 Microsoft Joins The Open 3D Foundation For Open Source 3D Development.md"};function D(f,o,m,T,x,w){const e=i("Link");return l(),u("div",null,[o[15]||(o[15]=a('<h1 id="微软加入开放-3d-基金会-参与开源-3d-开发" tabindex="-1">微软加入开放 3D 基金会，参与开源 3D 开发 <a class="header-anchor" href="#微软加入开放-3d-基金会-参与开源-3d-开发" aria-label="Permalink to “微软加入开放 3D 基金会，参与开源 3D 开发”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/05/microsoft-696x464.jpg" alt="微软"></p><p>微软已经以首席成员的身份加入了<ruby>开放 3D 基金会<rt>Open 3D Foundation</rt></ruby>（O3DF），其他首席成员是 Adobe、AWS、华为、英特尔和 Niantic。微软的参与为该项目带来了大量的知识和思想引领，这表明了：通过行业合作，创造一个高保真、功能齐全、不受商业条件限制的开源 3D 引擎是多么的关键。</p><p>微软首席集团项目经理 Paul Oliver 将加入 O3DF 管理委员会，这表明他将致力于实现基金会的目标，即确保符合开放 3D 社区保持需求与输入的平衡。基金会的战略方向和对 3D 可视化、仿真计划的管理，是由理事会与股东的创新互动来指导的。</p><p>“微软在创意方面的根基很深，我们希望帮助所有的创作者，无论他们是谁、在哪里、为哪个平台创作”，Oliver 如是说，“由 Linux 基金会创建的开放 3D 基金会，是朝着帮助更多世界各地的创作者迈出的美妙一步，我们很高兴能成为其中的一员。”</p><p>微软不断致力于使游戏制作民主化，并向全世界的游戏创作者提供其工具和技术。加入开放 3D 基金会也反映出这一点。微软去年通过 GitHub 向所有开发者发布了其游戏开发工具包，并正在通过与 O3DF 的新伙伴关系，扩大其向所有人开放技术的承诺。</p><p>O3DF 执行董事，兼 Linux 基金会的游戏和数字媒体部总经理 Royal O&#39;Brien 说：“我们很高兴微软以首席成员的身份加入开放 3D 基金会。有像微软这样杰出的行业资深公司做出贡献，并帮助社区推动 3D 引擎的创新，这对开源社区和使用它的公司都是巨大的好处。”</p><hr>',8)),p("p",null,[o[1]||(o[1]=t("via: ",-1)),n(e,{href:"https://www.opensourceforu.com/2022/05/microsoft-joins-the-open-3d-foundation-for-open-source-3d-development-promotion/"},{default:r(()=>[...o[0]||(o[0]=[t("https://www.opensourceforu.com/2022/05/microsoft-joins-the-open-3d-foundation-for-open-source-3d-development-promotion/",-1)])]),_:1})]),p("p",null,[o[6]||(o[6]=t("作者：",-1)),n(e,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:r(()=>[...o[2]||(o[2]=[t("Laveesh Kocher",-1)])]),_:1}),o[7]||(o[7]=t(" 选题：",-1)),n(e,{href:"https://github.com/lkxed"},{default:r(()=>[...o[3]||(o[3]=[t("lkxed",-1)])]),_:1}),o[8]||(o[8]=t(" 译者：",-1)),n(e,{href:"https://github.com/lkxed"},{default:r(()=>[...o[4]||(o[4]=[t("lkxed",-1)])]),_:1}),o[9]||(o[9]=t(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:r(()=>[...o[5]||(o[5]=[t("wxy",-1)])]),_:1})]),p("p",null,[o[12]||(o[12]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...o[10]||(o[10]=[t("LCTT",-1)])]),_:1}),o[13]||(o[13]=t(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:r(()=>[...o[11]||(o[11]=[t("Linux中国",-1)])]),_:1}),o[14]||(o[14]=t(" 荣誉推出",-1))])])}const F=s(d,[["render",D]]);export{v as __pageData,F as default};
